import MapRfid from "@/components/PresenceApp/PopUps/MapRfid.vue";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import moment from "moment";
import SnackBar from "@/components/SnackBar.vue";
import GeoSwipes from "@/components/PresenceApp/PopUps/GeoSwipes.vue";
import { list_all_organizations_swipes } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_location_details } from "@/mixins/GetLocations.js";
export default {
  components: {
    GeoSwipes,
    SnackBar,
    MapRfid
  },
  mixins: [get_location_details],
  data() {
    return {
      search: "",
      searchQuery: "",
      tableLoading: false,
      viewSwipeLocation: false,
      rfidMapping: false,
      modal: false,
      endmodal: false,
      next_token: null,
      selectedDate: "",
      minmonth: "",
      tableData: [],
      componentCheck: 0,
      SnackBarComponent: {},
      rowInfo: {},
      fixed: true,
      sortBy: [{
        key: "swiped_time",
        order: "desc"
      }],
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      headers: [{
        title: "Source",
        value: "swipe_source",
        sortable: true,
        align: "start"
      }, {
        title: "Member ID",
        value: "member_id",
        sortable: true,
        align: "start"
      }, {
        title: "Location Name",
        value: "location_name",
        sortable: true,
        align: "start"
      }, {
        title: "Member Name",
        value: "user_name",
        sortable: true,
        align: "start"
      }, {
        title: "Swipe Date/Time",
        value: "swiped_time",
        sortable: true,
        align: "start"
      }, {
        title: "Geo",
        value: "swipe_lat",
        sortable: false,
        align: "center"
      }],
      loaction: "ALL",
      loactionitems: [],
      goLoading: false,
      datePicker: false,
      datePickerTo: false,
      computedDateFormatted: this.formatDate(new Date()),
      dataFormatted: this.formatDate(new Date()),
      tempDate: null,
      tempDateTo: null,
      date: null,
      currentPage: 1,
      itemsPerPage: 20,
      totalItems: 0,
      windowHeight: 0,
      showFilterDrawer: false
    };
  },
  computed: {
    computedDateDisplay() {
      return this.displayFormatDate(this.computedDateFormatted);
    },
    dataDisplayFormatted() {
      return this.displayFormatDate(this.dataFormatted);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    activeFiltersCount() {
      let count = 0;

      // Count from date filter (if not default)
      if (this.computedDateFormatted && this.computedDateFormatted !== this.formatDate(new Date())) {
        count++;
      }

      // Count to date filter (if not default)
      if (this.dataFormatted && this.dataFormatted !== this.formatDate(new Date())) {
        count++;
      }

      // Count location filter
      if (this.loaction && this.loaction !== "ALL") {
        count++;
      }
      return count;
    }
  },
  async created() {
    this.windowHeight = window.innerHeight - 250;
    this.selectedDate = this.get_orgdate(this.$store.getters.GetUserObj.organization.organization_created_on);
    this.minmonth = moment(this.selectedDate, "MM/DD/YYYY").format("YYYY-MM-DD");
    await this.get_location_details();
    await this.get_swipe_logs();
    this.fetch_details();
  },
  watch: {
    currentPage(newVal, oldVal) {
      // When the page changes, check if we need to load more data
      if (newVal > oldVal && this.next_token) {
        // User is going to next page and we have more data to load
        this.get_swipe_logs();
      } else {
        // Just scroll to top of table for same page or going back
        const table = document.querySelector(".modern-data-table");
        if (table) table.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      }
    }
  },
  methods: {
    edit_Rfid(item) {
      this.componentCheck = 2;
      this.rowInfo = item;
      this.rfidMapping = true;
    },
    back_action() {
      this.$store.commit("SetattendenceBack", true);
      this.$router.push("/home/UserLevel");
    },
    displayFormatDate(date) {
      if (!date) return "";
      const [year, month, day] = date.split("-");
      return `${day}/${month}/${year}`;
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    getMinDateForFromDate() {
      // Get the current date
      const now = new Date();
      // Create a date for the 8th of the current month
      const minDate = new Date(now.getFullYear(), now.getMonth(), 8);

      // If current date is before 8th of the month, use 8th of previous month
      if (now.getDate() < 8) {
        minDate.setMonth(minDate.getMonth() - 1);
      }
      return minDate.toISOString().split("T")[0];
    },
    saveDate() {
      this.date = this.tempDate;
      this.computedDateFormatted = this.tempDate ? this.formatDate(this.tempDate) : "";
      this.datePicker = false;

      // Reset To Date if it's before the new From Date
      if (this.dataFormatted && this.computedDateFormatted > this.dataFormatted) {
        this.dataFormatted = this.computedDateFormatted;
        this.tempDateTo = this.tempDate;
      }
    },
    saveDateTo() {
      // Ensure To Date is not before From Date
      if (this.computedDateFormatted && this.tempDateTo < this.computedDateFormatted) {
        this.error_info("To Date cannot be before From Date");
        return;
      }
      this.date = this.tempDateTo;
      this.dataFormatted = this.tempDateTo ? this.formatDate(this.tempDateTo) : "";
      this.datePickerTo = false;
    },
    check_from_date(date) {
      this.$refs.dialog1.save(date);
      this.todate = new Date().toISOString().substr(0, 10);
    },
    get_orgdate(date) {
      let a = new Date(date * 1000).toLocaleTimeString("en-US", {
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit"
      });
      return a.toUpperCase();
    },
    fetch_details() {
      this.locationList.forEach(element => {
        this.loactionitems.push({
          title: element.location_name,
          location_id: element.location_id
        });
      });
      this.loactionitems.unshift({
        title: "All",
        location_id: "ALL"
      });
    },
    get_scanlogs_pagination() {
      this.tableData = [];
      this.currentPage = 1;
      this.goLoading = true;
      this.get_swipe_logs();
    },
    getcal() {
      this.modal = true;
    },
    get_swipe_pagination() {
      if (this.next_token) {
        this.get_swipe_logs();
      }
    },
    get_date(date) {
      return formatedatetime(date / 1000);
      // let a = new Date(date).toLocaleTimeString("en-In", {
      //   year: "numeric",
      //   month: "2-digit",
      //   day: "2-digit",
      //   hour: "2-digit",
      //   minute: "2-digit",
      //   second: "2-digit",
      // });
      // return a.toUpperCase();
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.next_token = null;
      this.tableData = [];
      this.rfidMapping = false;
      this.get_swipe_logs();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    get_location(item) {
      this.componentCheck = 1;
      this.rowInfo = item;
      this.viewSwipeLocation = true;
    },
    async get_swipe_logs() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_all_organizations_swipes, {
          input: {
            user_email_id: data.user.user_email_id,
            swipe_source: "QUERY",
            organization_id: data.organization.organization_id,
            from_date: this.computedDateFormatted,
            to_date: this.dataFormatted,
            limit: 100,
            nextToken: this.next_token,
            location_id: this.loaction
          }
        }));
        this.tableLoading = false;
        this.goLoading = false;
        var response = result.data.list_all_organizations_swipes;
        if (response.Status == "ERROR") {
          this.tableLoading = false;
          this.goLoading = false;
        } else {
          this.next_token = result.data.list_all_organizations_swipes.nextToken;
          let array = this.tableData.concat(response.data);
          this.tableData = array;
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.swipe_id === obj.swipe_id));
          this.tableData = uniqueArrayOfObjects;
          this.totalItems = this.tableData.length;
        }

        // } else {
        //   this.tableLoading = false;
        // }
      } catch (error) {
        this.tableLoading = false;
        this.goLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    openFilterDrawer() {
      this.showFilterDrawer = true;
    },
    closeFilterDrawer() {
      this.showFilterDrawer = false;
    },
    clear_data() {
      this.loaction = "ALL";
      this.computedDateFormatted = this.formatDate(new Date());
      this.dataFormatted = this.formatDate(new Date());
      this.get_scanlogs_pagination();
    },
    applyFilterFromDrawer() {
      this.get_scanlogs_pagination();
      this.showFilterDrawer = false;
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.paginateData();
    },
    getSortValue(value, key) {
      if (typeof value === "object" && key in value) {
        return value[key];
      }
      return value;
    },
    openFilterDrawer() {
      this.showFilterDrawer = true;
    },
    closeFilterDrawer() {
      this.showFilterDrawer = false;
    },
    clear_data() {
      this.loaction = "ALL";
      this.computedDateFormatted = this.formatDate(new Date());
      this.dataFormatted = this.formatDate(new Date());
      this.activeFiltersCount = 0;
      this.showFilterDrawer = false;
      this.get_scanlogs_pagination();
    },
    applyFilterFromDrawer() {
      this.get_scanlogs_pagination();
      this.showFilterDrawer = false;
    }
  }
};
